"use strict";(self.webpackChunk_otw_web_docusaurus=self.webpackChunk_otw_web_docusaurus||[]).push([[2397],{3752(a){a.exports=JSON.parse('{"title":"SPA\uc5d0\uc11c \ub370\uc774\ud130\ub294 \uc5b4\ub5bb\uac8c \ubc1b\uc544\uc62c\uae4c","date":"2024-06-12","coverUrl":null,"html":"<h2 data-notion-block-id=\\"a176ae33-902a-4127-bd50-3ebcca67c906\\" id=\\"a176ae33-902a-4127-bd50-3ebcca67c906\\">SPA\uc5d0\uc11c \ub370\uc774\ud130\ub294 \uc5b4\ub5bb\uac8c \ubc1b\uc544\uc62c\uae4c</h2><a href=\\"https://martinfowler.com/articles/data-fetch-spa.html\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://martinfowler.com/articles/data-fetch-spa.html</a><p data-notion-block-id=\\"35a859f9-4f92-4621-97f1-ed550381baa6\\"><b>\uc2ec\uc724\uc12d</b>: React\uc640 Vue\uc5d0\uc11c \uc77c\ubc18\uc801 fetch \ub85c\uc9c1\uc5d0\uc11c \uc2dc\uc791\ud574\uc11c loading, suspense, Fetch-On-Render / Fetch-Then-Render, parallel fetching\u2026\uac19\uc740 Fetch\uc5d0 \uad00\ub828\ub41c \uac70\uc758 \ubaa8\ub4e0 \uac1c\ub150\uc744 \ub9d0\ud574\uc8fc\ub294 \uae00\uc785\ub2c8\ub2e4. <code>@tanstack/query</code>\ub97c \uc0ac\uc6a9\ud558\uba74\uc11c Fetch \uc804\ub7b5\uc744 \uc0ac\uc6a9\ud558\ub294 \uac83\uc774 \uc790\uc5f0\uc2a4\ub7ec\uc6cc\uc84c\uc9c0\ub9cc \uc804\ub7b5\uc758 \uac1c\ub150\uc744 \ub2e4 \uc124\uba85\ud574\uc8fc\uc9c0 \uc54a\uae30 \ub54c\ubb38\uc5d0 \ubcfc \ub9cc\ud55c \uae00\uc774\ub77c\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"9c27ead7-8df1-4422-8566-9d197510a038\\" id=\\"9c27ead7-8df1-4422-8566-9d197510a038\\">Tanstack Query\uc5d0\uc11c\uc758 \uba54\ubaa8\ub9ac \ub204\uc218</h2><a href=\\"https://schiener.io/2024-05-29/react-query-leaks\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://schiener.io/2024-05-29/react-query-leaks</a><p data-notion-block-id=\\"9ea466b8-a25d-40a8-910e-db0ef64507e2\\"><b>\uc2ec\uc724\uc12d</b>: <a href=\\"https://ones-to-watch.ethansup.net/news/post/a5902c7d-ee33-4db6-aaea-ea4820a7562f#969cfc7b-5f89-42de-896d-eacff8b32799\\">React\uc5d0\uc11c\uc758 \uba54\ubaa8\ub9ac \ub204\uc218</a>\uc640 \uac19\uc740 \uc800\uc790\uac00 \uc4f4 \uae00\uc785\ub2c8\ub2e4. Tanstack Query\uc5d0\uc11c\uc758 \ub204\uc218\ub77c\uace0 \ud558\uc9c0\ub9cc, \ucef4\ud3ec\ub10c\ud2b8 \uc548\uc5d0\uc11c\uc758 \ud568\uc218 \uc120\uc5b8\uc744 \uc870\uc2ec\ud558\ub77c\ub294 \uae00\uacfc \uac19\ub2e4\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4. \uc5ec\uae30\uc11c \uc81c\uacf5\ud558\ub294 \ud574\uacb0\ubc29\uc2dd \ub9d0\uace0\ub3c4 <a href=\\"https://tanstack.com/query/latest/docs/framework/react/reference/queryOptions\\">queryOptions</a>\ub77c\ub294 \ud574\uacb0\ucc45\ub3c4 \uc788\uc2b5\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"95dd20dc-c9a1-44b9-8774-d9991274eb6b\\" id=\\"95dd20dc-c9a1-44b9-8774-d9991274eb6b\\">CSS gap\uc744 \uc0ac\uc6a9\ud558\uc138\uc694.</h2><a href=\\"https://ishadeed.com/article/the-gap/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://ishadeed.com/article/the-gap/</a><p data-notion-block-id=\\"39035669-c5d8-4339-be76-812d5dbea8ea\\"><b>\uc2ec\uc724\uc12d</b>: flex\uac00 \ub3c4\uc785\ub418\uae30 \uc774\uc804\uc5d0\ub294 \uc694\uc18c \uc0ac\uc774\uc758 \uac04\uaca9\uc744 margin\uacfc CSS \uc120\ud0dd\uc790\ub97c \ud65c\uc6a9\ud574 \ucc98\ub9ac\ud588\uc2b5\ub2c8\ub2e4. \uac80\uc0c9\ud558\uba74 gap\uc5d0 \ub300\ud55c \ub2f5\uc774 \ub9ce\uc774 \uc548 \ub098\uc624\ub294 \uac83\ub3c4 \ud55c \ubaab\ud588\uad6c\uc694. <a href=\\"https://ones-to-watch.ethansup.net/news/post/b6be5023-1604-4d2d-9f86-d1888a427413#33710ab4-f781-493a-aaf6-1812739d7fd9\\"><code>contrast-color()</code></a><a href=\\"https://ones-to-watch.ethansup.net/news/post/b6be5023-1604-4d2d-9f86-d1888a427413#33710ab4-f781-493a-aaf6-1812739d7fd9\\">\uc5d0 \ub300\ud55c \uc0dd\uac01\ub4e4</a>\uc5d0\uc11c \ub9d0\ud588\ub4ef\uc774, CSS \uc2e0 \uae30\uc220\uc774 \uac1c\ubc1c\uc790\ub4e4\uc5d0\uac8c \ub2ff\uc73c\ub824\uba74 \uc624\ub798 \uac78\ub9ac\uc9c0\ub9cc, \ud300\uc6d0\ub4e4\uc5d0\uac8c \ud37c\ud2b8\ub824\uc11c \uc0ac\uc6a9\ucc98\ub97c \ub298\ub9ac\ub294\uac8c \uc911\uc694\ud558\ub2e4\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"25d01336-8956-4d7d-b9b3-814af129a490\\" id=\\"25d01336-8956-4d7d-b9b3-814af129a490\\">DOM depth\ub97c \uc904\uc774\uc138\uc694.</h2><a href=\\"https://frontendatscale.com/blog/how-deep-is-your-dom/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://frontendatscale.com/blog/how-deep-is-your-dom/</a><p data-notion-block-id=\\"729e16e5-abf5-438e-af09-4ee635c06451\\"><b>\uc2ec\uc724\uc12d</b>: \uc800\uc790\uc758 \uac04\ub2e8\ud55c \uc2e4\ud5d8\uc73c\ub85c DOM depth\uac00 \ucee4\uc9c0\uba74 \ucee4\uc9c8\uc218\ub85d HTML \ud30c\uc2f1\uacfc CSS \ud2b8\ub9ac \uc0dd\uc131\uc5d0 \ucc28\uc9c8\uc774 \uc0dd\uae30\ub294 \uac83\uc744 \ud655\uc778\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. \ud56d\uc0c1 \uc2e0\uacbd\uc744 \uace4\ub450\uc138\uc6b8\ub9cc\ud55c \ubd80\ubd84\uc740 \uc544\ub2c8\uc9c0\ub9cc, \uc8fc\uae30\ub9c8\ub2e4 \ud55c \ubc88\uc529 \uccb4\ud06c\ud558\ub294 \uac83\uc740 \ud544\uc694\ud574\ubcf4\uc774\ub124\uc694.</p><h2 data-notion-block-id=\\"30607141-7ac8-4086-95ad-482bf45ebf31\\" id=\\"30607141-7ac8-4086-95ad-482bf45ebf31\\">Micro Frontends\u2026?</h2><a href=\\"https://martinfowler.com/articles/micro-frontends.html\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://martinfowler.com/articles/micro-frontends.html</a><p data-notion-block-id=\\"619fa62d-4277-47dc-82f2-002f8678a460\\"><b>\uc2ec\uc724\uc12d</b>: MSA\uc5d0 \ub300\ud574\uc11c\ub294 <a href=\\"https://ones-to-watch.ethansup.net/news/post/298d028d8e9c4d13b87a3ae9f00712fa#fbbf97c6-289b-4081-a48b-56fac37f7853\\">HTMX\uc5d0 \ub300\ud55c \uc758\uacac\ub4e4</a>\uc5d0\uc11c <a href=\\"https://danluu.com/simple-architectures/\\">\ub2e8\uc21c\ud55c \uc544\ud0a4\ud14d\uccd0 \ubc29\uc5b4\ud558\uae30</a>\ub77c\ub294 \uae00\ub85c\ub9cc \uac04\uc811\uc801\uc73c\ub85c \uc18c\uac1c\ud588\uc5c8\ub294\ub370, \uc6b0\uc544\ud55c \ud615\uc81c\ub4e4\uc758 <a href=\\"https://techblog.woowahan.com/16910/\\">\uc6f9 \uc560\ud50c\ub9ac\ucf00\uc774\uc158 \ud398\uc774\uc9c0\ub97c \ud328\ud0a4\uc9c0\ub85c \uac1c\ubc1c\ud574 \ubcf8 \uacbd\ud5d8 \uacf5\uc720</a>\uc5d0\uc11c Micro Frontends\uc758 \uae30\ubc95 \uc911 \ud558\ub098\uc778 Module Federation\uc744 \uc18c\uac1c\ud558\uae38\ub798 \uadf8 \uc0c1\uc704 \uac1c\ub150\uc778 Micro Frontends\uc744 \uc815\ub9ac\ud55c \uae00\uc744 \uac00\uc838\uc654\uc2b5\ub2c8\ub2e4. Module Federation\uc740 \ubc1c\uc804\ud558\uace0 \uc788\uace0(\uc774\uc804\uc5d0\ub3c4 \uc801\uc6a9\ud55c <a href=\\"https://blog.gangnamunni.com/post/saas-microfrontends/\\">\uac15\ub0a8\uc5b8\ub2c8</a>\uc758 \uc0ac\ub840\ub3c4 \uc788\uc8e0), \ub124\ud2b8\uc6cc\ud06c \uc18d\ub3c4\ub9cc \ucda9\ubd84\ud558\ub2e4\uba74 \uc774\uc0c1\uc801\uc774\uc9c0\ub9cc GraphQL\uacfc \ub3d9\uc77c\ud558\uac8c \ud2b9\uc815 \uc0c1\ud669\uc744 \ud574\uacb0\ud558\uae30 \uc704\ud574 \ub9cc\ub4e4\uc5b4\uc9c4 \ub3c4\uad6c\uc774\ub2c8 \ucda9\ubd84\ud788 \uace0\ub824 \ud6c4\uc5d0 \uc801\uc6a9\ud558\ub294 \uac83\uc774 \uc911\uc694\ud558\ub2e4\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4. \ub610\ud55c <a href=\\"https://blogs.mulesoft.com/dev-guides/microservices/is-this-the-end-of-microservices/\\">MSA\ub294 \uc774\uc81c \ub05d\uc778\uac00\uc694?</a>\uc5d0\uc11c\ub3c4 \ub9d0\ud558\ub4ef\uc774, MSA\ub294 \uc778\ud504\ub77c \ubfd0\ub9cc \uc544\ub2c8\ub77c \uc11c\ube44\uc2a4, \uac1c\ubc1c\ubb38\ud654, \uc18c\ud1b5 \ubc29\uc2dd\uae4c\uc9c0 \ud3ec\ud568\ub418\uc5b4 \uc788\uc2b5\ub2c8\ub2e4. \ub9ce\uc740 \uac83\uc744 \uace0\ub824\ud574\uc57c \ud558\uaca0\ub124\uc694.</p><h2 data-notion-block-id=\\"5856e01d-dcf4-4a3c-bb85-a65a244f2908\\" id=\\"5856e01d-dcf4-4a3c-bb85-a65a244f2908\\">Promise\uc758 \uc5ed\uc0ac</h2><a href=\\"https://www.joshwcomeau.com/javascript/promises/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.joshwcomeau.com/javascript/promises/</a><p data-notion-block-id=\\"bab48570-463e-4323-86f9-0a5d0d83e11d\\">Promise\uc758 \uc5ed\uc0ac\uc5d0 \ub300\ud574 \uce5c\uc808\ud558\uac8c \ud480\uc5b4\ub193\uc740 \uae00\uc785\ub2c8\ub2e4. \ub354 \uae4a\uac8c \uc54c\uc544\ubcf4\uc2e4 \uc608\uc815\uc774\ub77c\uba74 JavaScript Info\uc758 <a href=\\"https://ko.javascript.info/async\\">\ud504\ub77c\ubbf8\uc2a4\uc640 async, await</a>\ud30c\ud2b8\ub97c \ubcf4\uc2dc\ub294 \uac83\uc744 \ucd94\ucc9c\ud569\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"095ba9fe-9644-4935-a501-731f662d3da5\\" id=\\"095ba9fe-9644-4935-a501-731f662d3da5\\">\uc81c\ubc1c Skip to main content \ub9cc\ub4e4\uc5b4\uc8fc\uc138\uc694.</h2><a href=\\"https://technicalwriting.dev/a11y/skip.html\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://technicalwriting.dev/a11y/skip.html</a><p data-notion-block-id=\\"e91566d3-2de2-4296-b1aa-437d97f66e4f\\">\uc811\uadfc\uc131\uc744 \uc704\ud574 Skip to main content\ub97c \ub9cc\ub4e4\uc5b4\ub2ec\ub77c\ub294 \uac00\ubcbc\uc6b4 \uae00\uc785\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"3f7cfa99-bf4c-4f6e-bbd3-b2a48986eb21\\" id=\\"3f7cfa99-bf4c-4f6e-bbd3-b2a48986eb21\\">Storybook\uc758 type-safe mocking \uc811\uadfc\ubc95</h2><a href=\\"https://storybook.js.org/blog/type-safe-module-mocking/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://storybook.js.org/blog/type-safe-module-mocking/</a><p data-notion-block-id=\\"31d21eb2-f819-459e-b385-7a70f70eb1ad\\">Storybook\uc5d0\uc11c Jest\ub098 Vitest\uc758 mocking \uc811\uadfc\ubc95(mocks \ud3f4\ub354\ub97c \ud0d0\uc0c9\ud558\uac70\ub098 \ud14c\uc2a4\ud2b8 \ud30c\uc77c \uc548\uc5d0\uc11c mocking \ub458 \ub2e4 \ud5c8\uc6a9\ud558\ub294 \ubc29\uc2dd)\uacfc \ub2e4\ub974\uc9c0\ub9cc \ud45c\uc900\uc5d0 \ub9de\ucd98 \uc811\uadfc\ubc95\uc744 \uc18c\uac1c\ud569\ub2c8\ub2e4. Mocking\uc774 \uc774\ub8e8\uc5b4\uc9c0\ub294 \uc704\uce58\ub97c \ubd84\uba85\ud558\uac8c \ud558\uace0 type-safe\ub3c4 \ucc59\uae38 \uc218 \uc788\ub2e4\uace0 \uc18c\uac1c\ud569\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"aa326ae7-4623-4cf3-8c84-5ae90222d16c\\" id=\\"aa326ae7-4623-4cf3-8c84-5ae90222d16c\\">Framer Motion\uc744 \ub300\uccb4\ud558\ub294 CSS \uc2e0\uae30\uc220</h2><a href=\\"https://motion.dev/blog/do-you-still-need-framer-motion\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://motion.dev/blog/do-you-still-need-framer-motion</a><p data-notion-block-id=\\"aa936f0b-287d-4840-ab9b-7ed57f36ed6f\\">\ud604\uc7ac \ucd9c\uc2dc\ud558\uac70\ub098 \ucd9c\uc2dc \ud560 \uc608\uc815\uc778 CSS \uae30\ub2a5\ub4e4\uc744 Framer Motion\uc758 \uae30\ub2a5\uacfc \uc5f0\uacb0\uc9c0\uc5b4 \uc18c\uac1c\ud558\ub294 \uae00\uc785\ub2c8\ub2e4. CSS \uc2e0\uae30\ub2a5\uc740 \uc88b\uc9c0\ub9cc \ucd9c\uc2dc\ud558\uace0 \uc548\uc815\uc801\uc774\uac8c \ub418\ub824\uba74 \uc2dc\uac04\uc774 \uac78\ub9ac\uae30 \ub54c\ubb38\uc5d0 CSS\uc5d0 \uc774\ub7ec\ud55c \uc2e0 \uae30\ub2a5\uc774 \uc788\uc744 \uc608\uc815\uc774\ub2e4\ub9cc \uc54c\uace0 \uacc4\uc2dc\uba74 \uc88b\ub2e4\uace0 \uc0dd\uac01\ud569\ub2c8\ub2e4.</p><h2 data-notion-block-id=\\"d6fe4e0b-7fdc-4203-81a7-dcf667c5da3a\\" id=\\"d6fe4e0b-7fdc-4203-81a7-dcf667c5da3a\\">SSR\uc5d0\uc11c JSX \uc18d\ub3c4 \ube60\ub974\uac8c \ud558\uae30</h2><a href=\\"https://marvinh.dev/blog/speeding-up-javascript-ecosystem-part-9/\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://marvinh.dev/blog/speeding-up-javascript-ecosystem-part-9/</a><p data-notion-block-id=\\"b0cd6467-4643-4aae-bd45-1dbcb0bb7eb6\\">React\uc5d0\uc11c \ud0dc\uadf8\ub97c <code>React.createElement</code>\ub85c \ubcc0\ud658\ud558\ub294 \uac83 \ub300\uc2e0 String\uc73c\ub85c \ub9cc\ub4e4\uc5b4\uc11c \uc0bd\uc785\ud558\ub294 \ubc29\uc2dd\uc73c\ub85c \ubcc0\ud658\ud574\uc11c \ubcc0\ud658 \uc18d\ub3c4\ub97c \ube60\ub974\uac8c \ud558\uaca0\ub2e4\ub294 \uae00\uc785\ub2c8\ub2e4. \uac00\ubccd\uac8c \ubcfc\ub9cc\ud55c \uae00\uc774\ub124\uc694.</p><h2 data-notion-block-id=\\"365735b5-383c-4536-9eb4-0cb2ceffe9cf\\" id=\\"365735b5-383c-4536-9eb4-0cb2ceffe9cf\\">Corepack \uc0ac\uc6a9\ubc95</h2><a href=\\"https://www.totaltypescript.com/how-to-use-corepack\\" class=\\"bookmark-link\\" target=\\"_blank\\" rel=\\"noreferrer\\">https://www.totaltypescript.com/how-to-use-corepack</a><p data-notion-block-id=\\"86c8433d-a576-4c78-a0a0-a69357d3453e\\">Corepack\uc740 Node.js 14\ubc84\uc804\ubd80\ud130 \uc2dc\uc791\ub41c \ub2e4\ub978 \ud328\ud0a4\uc9c0 \ub9e4\ub2c8\uc800\ub97c \uc0ac\uc6a9\ud558\uae30 \uc27d\uace0 \ud328\ud0a4\uc9c0 \ub9e4\ub2c8\uc800\ub97c \uace0\uc815\ud558\ub294 \ub0b4\uc7a5 \ub77c\uc774\ube0c\ub7ec\ub9ac\uc785\ub2c8\ub2e4. \uac04\ub2e8\ud558\uac8c \uc18c\uac1c\ud558\ub294 \uc0ac\uc6a9\ubc95\uc744 \ubcf4\uace0 \uc0ac\uc6a9\ud574\ubcf4\uc138\uc694. \ub2e4\ub978 Node.js \uae30\ub2a5\uc744 \uc54c\uc544\ubcf4\ub824\uba74 <a href=\\"https://snyk.io/blog/10-modern-node-js-runtime-features/\\">10\uac00\uc9c0 \ubaa8\ub358 Node.js \ub7f0\ud0c0\uc784 \uae30\ub2a5</a>\uc744 \ubcf4\uc138\uc694.</p>"}')}}]);